export interface TranslationMessages {
    [key: string]: string | TranslationMessages;
}
export interface UseTranslationParams {
    /** The micro-frontend name (e.g., 'analytics', 'vendor-management') */
    mfe: string;
    /** The locale code (e.g., 'pt-BR', 'en-US', 'es-419') */
    locale: string;
    /** Local fallback messages if BFF fails or is disabled (can be nested or flattened) */
    fallbackMessages?: TranslationMessages | Record<string, string>;
    /** Enable fetching from BFF. Set to false to use only local fallbacks */
    enableBFF?: boolean;
}
export interface UseTranslationReturn {
    /** Translation messages object (flattened with dot notation) */
    messages: Record<string, string>;
    /** Loading state when fetching from BFF */
    isLoading: boolean;
    /** Error state */
    hasError: boolean;
    /** Error object if fetch failed */
    error: any;
    /** Indicates if the fetch was successful and valid data was received from the server */
    isSuccessful: boolean;
}
